contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint amount) public payable {
        require(amount >= 10, "must send at least 10");
        require(address(this).balance >= amount, "not enough balance");

        address bankAddr = c.bank();
        uint potBefore = c.pot();
        uint cBalanceBefore = address(c).balance;
        uint bankBalanceBefore = bankAddr.balance;
        uint selfBalanceBefore = address(this).balance;

        bool reverted;
        try c.play{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint potAfter = c.pot();
        uint cBalanceAfter = address(c).balance;
        uint bankBalanceAfter = bankAddr.balance;
        uint selfBalanceAfter = address(this).balance;

        bool bankNotSelf = bankAddr != address(this);
        bool exactTicket = amount == 10;
        bool win = potAfter == 0;
        bool noWin = !win;

        // General rule: if the call succeeds, the bank never loses Ether and the
        // contract's balance never decreases. For an exact ticket when the bank
        // is not the caller, the caller either simply loses the ticket amount,
        // or wins and receives at least the previous pot minus 1, and the pot is
        // either reset to 0 (win) or increased by the ticket amount (no win).
        assert(
            reverted ||
            (
                bankBalanceAfter >= bankBalanceBefore &&
                cBalanceAfter >= cBalanceBefore &&
                (
                    !exactTicket ||
                    !bankNotSelf ||
                    (
                        (win && potBefore > 0 && selfBalanceAfter >= selfBalanceBefore - amount + potBefore - 1) ||
                        (noWin && potAfter == potBefore + amount && selfBalanceAfter == selfBalanceBefore - amount)
                    )
                )
            )
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
