    }

    function run() public payable {
        // The bank (and thus the constructor sender) is this test contract, so a
        // losing play sends no Ether out of c.  We can make the call succeed
        // without adding any precondition on parameters; the ticket amount is a
        // required parameter but is not exposed to the test, so we send exactly
        // the ticket amount.
        uint amount = 10;
        require(address(this).balance >= amount, "not enough balance");

        uint potBefore = c.pot();
        uint cBalanceBefore = address(c).balance;

        c.play{value: amount}();

        uint potAfter = c.pot();
        uint cBalanceAfter = address(c).balance;

        // In a losing outcome, the pot is increased by the ticket amount and the
        // contract's Ether balance also increases by the ticket amount; no Ether
        // is transferred out of c.
        bool isLost = potAfter != 0;

        assert(!isLost || (potAfter == potBefore + amount && cBalanceAfter == cBalanceBefore + amount));
    }

    receive() external payable {}
}

