contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint priorPot) public payable {
        // Setup: increase the pot by playing enough times so that pot >= priorPot (but not too many to avoid huge costs).
        // We'll play until pot >= priorPot or until we've played enough times (limit 10).
        require(priorPot <= 100); // bound to keep the test feasible
        uint i = 0;
        while (c.pot() < priorPot && i < 10) {
            c.play{value: 10}();
            i++;
        }
        // If we couldn't reach priorPot, skip the test (precondition not met).
        require(c.pot() >= priorPot);

